// Changes: Behaviour of roving-focus movement in a data grid (precedence relation grid).

import { describe, expect, it } from 'vitest'
import { clampCell, gridMove } from './gridFocus'

const size = { rows: 3, cols: 4 }
const mid = { row: 1, col: 1 }

describe('gridMove', () => {
  it('moves one cell with the arrow keys', () => {
    expect(gridMove({ key: 'ArrowUp' }, mid, size)).toEqual({ row: 0, col: 1 })
    expect(gridMove({ key: 'ArrowDown' }, mid, size)).toEqual({ row: 2, col: 1 })
    expect(gridMove({ key: 'ArrowLeft' }, mid, size)).toEqual({ row: 1, col: 0 })
    expect(gridMove({ key: 'ArrowRight' }, mid, size)).toEqual({ row: 1, col: 2 })
  })

  it('has no target past an edge (the key must keep its native scrolling)', () => {
    expect(gridMove({ key: 'ArrowUp' }, { row: 0, col: 2 }, size)).toBeNull()
    expect(gridMove({ key: 'ArrowLeft' }, { row: 2, col: 0 }, size)).toBeNull()
    expect(gridMove({ key: 'ArrowDown' }, { row: 2, col: 2 }, size)).toBeNull()
    expect(gridMove({ key: 'ArrowRight' }, { row: 0, col: 3 }, size)).toBeNull()
  })

  it('Home / End go to the first / last cell of the row', () => {
    expect(gridMove({ key: 'Home' }, mid, size)).toEqual({ row: 1, col: 0 })
    expect(gridMove({ key: 'End' }, mid, size)).toEqual({ row: 1, col: 3 })
  })

  it('Ctrl+Home / Ctrl+End go to the first / last cell of the grid', () => {
    expect(gridMove({ key: 'Home', ctrlKey: true }, mid, size)).toEqual({ row: 0, col: 0 })
    expect(gridMove({ key: 'End', ctrlKey: true }, mid, size)).toEqual({ row: 2, col: 3 })
  })

  it('has no target when the key would not move focus', () => {
    expect(gridMove({ key: 'Home' }, { row: 1, col: 0 }, size)).toBeNull()
    expect(gridMove({ key: 'End', ctrlKey: true }, { row: 2, col: 3 }, size)).toBeNull()
  })

  it('leaves modified keys to the browser (only Ctrl+Home / Ctrl+End are grid keys)', () => {
    expect(gridMove({ key: 'ArrowRight', ctrlKey: true }, mid, size)).toBeNull()
    expect(gridMove({ key: 'ArrowDown', altKey: true }, mid, size)).toBeNull()
    expect(gridMove({ key: 'ArrowLeft', shiftKey: true }, mid, size)).toBeNull()
    expect(gridMove({ key: 'ArrowUp', metaKey: true }, mid, size)).toBeNull()
    expect(gridMove({ key: 'End', shiftKey: true }, mid, size)).toBeNull()
  })

  it('ignores keys that are not navigation keys', () => {
    expect(gridMove({ key: '<' }, mid, size)).toBeNull()
    expect(gridMove({ key: 'Enter' }, mid, size)).toBeNull()
  })
})

describe('clampCell', () => {
  it('keeps a cell that is still inside the grid', () => {
    expect(clampCell({ row: 2, col: 3 }, size)).toEqual({ row: 2, col: 3 })
  })

  it('moves a cell left outside a shrunken grid to the nearest remaining cell', () => {
    expect(clampCell({ row: 5, col: 1 }, size)).toEqual({ row: 2, col: 1 })
    expect(clampCell({ row: 1, col: 9 }, size)).toEqual({ row: 1, col: 3 })
  })
})
